const rows = $input.all().map(i => i.json);
const m = {};
for (const r of rows) { if (r['Key']) m[String(r['Key']).trim()] = r['Value']; }
const bool = (v, d) => (v === undefined || v === '') ? d : ['true','yes','1'].includes(String(v).trim().toLowerCase());
const num = (v, d) => { const n = parseInt(v); return isNaN(n) ? d : n; };
return [{ json: {
  dailyLimit: num(m.dailyLimit, 2), findLimit: num(m.findLimit, 5),
  testMode: bool(m.testMode, true), testEmail: String(m.testEmail || '').trim(),
  autoApprove: bool(m.autoApprove, false),
  senderName: m.senderName || 'Your Name', signatureExtra: m.signatureExtra || '',
  optOutLine: m.optOutLine || "If this isn't relevant, just reply 'no' and I won't email again.",
  hunterMode: String(m.hunterMode || 'fallback').trim().toLowerCase(),
  followUpDay2: num(m.followUpDay2, 3), followUpDay3: num(m.followUpDay3, 4), gapMinutes: num(m.gapMinutes, 2)
}}];

const offers = $input.all().map(i => i.json)
  .filter(o => o['Offer Name']).filter(o => String(o['Active'] || '').trim().toLowerCase() === 'yes')
  .map(o => ({ name: o['Offer Name'], skill: o['Skill'] || '', pain: o['Pain Signals'] || '', pitch: o['Pitch Angle'] || '', target: o['Target Companies'] || '', region: o['Region'] || '', demo: o['Demo Link'] || '' }));
return [{ json: { offers } }];

const rows = $input.all().map(i => i.json);
const domains = new Set(); const emails = new Set();
for (const r of rows) {
  const w = String(r['Website'] || '').replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase();
  if (w) domains.add(w);
  if (r['Email']) emails.add(String(r['Email']).toLowerCase());
}
return [{ json: { existingDomains: [...domains], existingEmails: [...emails] } }];

const offers = $('Pick Active Offers').first().json.offers || [];
const today = new Date().toISOString().slice(0, 10);
return offers.map(o => ({ json: { ...o, prompt:
`You help a freelance ML/AI engineer find B2B clients. Write 4 web search queries that return the HOMEPAGES of small and mid-size companies, meaning the businesses themselves (the potential clients).
Never target: blogs, "best/top" lists, directories, job boards, news, social media, or agencies/vendors that sell AI, software or automation (they are competitors, not clients).
Target companies: ${o.target}
Region: ${o.region}
Manual or costly work they likely still do by hand: ${o.pain}
Service we would offer: ${o.name} (${o.skill})
Query style: name the type of business plus a place plus a trait, then add "about us" or "contact us". Example: "family-owned food packaging manufacturer Texas about us". Do NOT use the words best, top, list, guide, companies in, providers, software, AI, solutions or vendors in any query.
Today is ${today}; vary the angle and the city so results differ from earlier days.
Return ONLY a JSON array like [{"query":"..."}]. No other text.` } }));

const offers = $('Build Keyword Prompts').all();
const out = [];
$input.all().forEach((item, i) => {
  const o = offers[i].json;
  let list = [];
  try {
    const t = item.json.choices[0].message.content;
    list = JSON.parse(t.match(/\[[\s\S]*\]/)[0]).filter(x => x && x.query);
  } catch (e) {}
  if (!list.length) list = [{ query: `${o.target} ${o.region}`.slice(0, 120) }];
  for (const x of list.slice(0, 4)) out.push({ json: { offerName: o.name, query: x.query } });
});
return out;

const kws = $('Parse Keywords').all();
const blocked = ['linkedin.com','facebook.com','instagram.com','twitter.com','x.com','youtube.com','tiktok.com','reddit.com','quora.com','medium.com','upwork.com','fiverr.com','freelancer.com','clutch.co','g2.com','capterra.com','wikipedia.org','github.com','pinterest.com','yelp.com','trustpilot.com','crunchbase.com','glassdoor.com','indeed.com','forbes.com','hubspot.com','zapier.com','amazon.com','alibaba.com','gov','edu'];
const junkTitle = /\b(best|top|guide|how to|vs|versus|list of|review|reviews|ideas|examples|trends|statistics|companies in|suppliers in|providers in)\b/i;
const junkPath = /\/(blog|blogs|news|article|articles|post|posts|resources|guides|insights|press|learn|glossary|case-stud)/i;
const out = []; const seen = new Set();
$input.all().forEach((item, i) => {
  const offerName = kws[i] ? kws[i].json.offerName : '';
  for (const r of (item.json.results || [])) {
    const m = String(r.url || '').match(/^(https?:\/\/)([^\/?#:]+)/i);
    if (!m) continue;
    const domain = m[2].replace(/^www\./i, '').toLowerCase();
    const origin = m[1].toLowerCase() + m[2].toLowerCase();
    if (blocked.some(b => domain === b || domain.endsWith('.' + b))) continue;
        if (/(^|\.)(gov|edu|mil)(\.[a-z]{2})?$/.test(domain) || /(^|\.)(alberta|ontario|canada|gc|bcgov|nhs)\.(ca|uk)$/.test(domain)) continue;
    if (junkTitle.test(r.title || '') || junkPath.test(String(r.url))) continue;
    if (seen.has(domain)) continue;
    seen.add(domain);
    out.push({ json: { companyName: (r.title || domain).split(/[|\-–—]/)[0].trim(), website: origin, domain,
      evidence: (r.content || '').replace(/\s+/g, ' ').slice(0, 300), offerName } });
  }
});
return out;

const ex = new Set($('Tag Existing').first().json.existingDomains || []);
const limit = $('Parse Settings (Find)').first().json.findLimit;
const byOffer = {};
for (const i of $input.all()) {
  if (ex.has(i.json.domain)) continue;
  (byOffer[i.json.offerName] = byOffer[i.json.offerName] || []).push(i);
}
const groups = Object.values(byOffer);
const out = [];
for (let k = 0; out.length < limit; k++) {
  let added = false;
  for (const g of groups) { if (g[k] && out.length < limit) { out.push(g[k]); added = true; } }
  if (!added) break;
}
return out;

const BAD = /\.(png|jpe?g|gif|svg|webp|css|js|ico)$|example\.|sentry|wixpress|godaddy|domain\.com|yourdomain|email\.com|noreply|no-reply|donotreply|u003e/i;
const pull = html => {
  const set = new Set();
  for (const m of (html.match(/mailto:([^"'?\s>]+)/gi) || [])) { try { set.add(decodeURIComponent(m.slice(7)).toLowerCase()); } catch (e) {} }
  for (const m of (html.match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/gi) || [])) set.add(m.toLowerCase());
  return [...set].filter(e => !BAD.test(e));
};
const textOf = r => (r && typeof r.data === 'string') ? r.data : '';
const base = $('Dedup & Limit').all();
const out = [];
$input.all().forEach((item, i) => {
  const b = base[i].json;
  const html = textOf(item.json).replace(/<style[\s\S]*?<\/style>/gi, '');
  const meta = (html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']+)/i) || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]*name=["']description["']/i) || [])[1] || '';
  const title = ((html.match(/<title[^>]*>([^<]+)/i) || [])[1] || '').trim();
  let contactUrl = '';
  for (const m of html.matchAll(/href=["']([^"'#]+)["']/gi)) {
    const href = m[1].trim();
    if (!/contact|about|reach-us|get-in-touch|connect/i.test(href)) continue;
    if (/^(mailto|tel|javascript):/i.test(href)) continue;
    let full;
    if (/^https?:\/\//i.test(href)) full = href;
    else if (href.startsWith('//')) full = 'https:' + href;
    else if (href.startsWith('/')) full = b.website + href;
    else full = b.website + '/' + href;
    const hm = full.match(/^https?:\/\/([^\/?#:]+)/i);
    if (hm && hm[1].replace(/^www\./i, '').toLowerCase() === b.domain) { contactUrl = full; break; }
  }
  const parts = title.replace(/&amp;/g, '&').split(/\s*[|\-–—:]\s*/).map(s => s.trim()).filter(s => s && !/^(home|homepage|welcome|official site)$/i.test(s));
out.push({ json: { ...b, companyName: parts.find(s => s.length >= 2 && s.length <= 50) || b.companyName, pageTitle: title, metaDesc: meta.replace(/\s+/g, ' ').slice(0, 300), contactUrl, homeEmails: pull(html) } });
});
return out;

const BAD = /\.(png|jpe?g|gif|svg|webp|css|js|ico)$|example\.|sentry|wixpress|godaddy|domain\.com|yourdomain|email\.com|noreply|no-reply|donotreply|u003e/i;
const GENERIC = /^(info|contact|hello|hi|sales|support|admin|office|enquiries|inquiries|mail|team|service|help|customerservice)@/i;
const FREE = /@(gmail|yahoo|outlook|hotmail|icloud|aol)\./i;
const pull = html => {
  const set = new Set();
  for (const m of (html.match(/mailto:([^"'?\s>]+)/gi) || [])) { try { set.add(decodeURIComponent(m.slice(7)).toLowerCase()); } catch (e) {} }
  for (const m of (html.match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/gi) || [])) set.add(m.toLowerCase());
  return [...set].filter(e => !BAD.test(e));
};
const textOf = r => (r && typeof r.data === 'string') ? r.data : '';
const base = $('Parse Homepage').all();
const taken = new Set($('Tag Existing').first().json.existingEmails || []);
const out = [];
$input.all().forEach((item, i) => {
  const b = base[i].json;
  const all = [...new Set([...(b.homeEmails || []), ...pull(textOf(item.json))])].filter(e => !taken.has(e));
  const sameDomain = e => e.split('@')[1] === b.domain || e.split('@')[1].endsWith('.' + b.domain);
  const rank = e => (sameDomain(e) ? (GENERIC.test(e) ? 2 : 3) : (FREE.test(e) ? 1 : 0));
  all.sort((x, y) => rank(y) - rank(x));
  const best = all.find(e => rank(e) > 0) || '';
  out.push({ json: { companyName: b.companyName, website: b.website, domain: b.domain, offerName: b.offerName,
    evidence: b.metaDesc || b.evidence || b.pageTitle || '',
    siteEmail: best, siteEmailType: best ? (GENERIC.test(best) || FREE.test(best) ? 'generic' : 'personal') : '' } });
});
return out;

const base = $('Needs Hunter?').all(0);
const goodRole = /owner|founder|ceo|president|director|head|manager|operations|coo|cto|general|partner|principal/i;
const taken = new Set($('Tag Existing').first().json.existingEmails || []);
const out = [];
$input.all().forEach((item, i) => {
  const c = base[i].json;
  const d = (item.json && item.json.data) || {};
  const list = (d.emails || []).filter(e => e.value && (e.confidence || 0) >= 60 && !taken.has(String(e.value).toLowerCase()));
  const score = e => (e.type === 'personal' ? 100 : 0) + (goodRole.test((e.position || '') + ' ' + (e.department || '')) ? 50 : 0) + (e.confidence || 0) / 10;
  list.sort((a, b) => score(b) - score(a));
  const best = list[0];
  if (best) {
    out.push({ json: { companyName: d.organization || c.companyName, website: c.website, email: best.value, contactName: best.first_name || '',
      offerName: c.offerName, evidence: c.evidence, emailNote: 'email via Hunter' + (best.position ? ' (' + best.position + ')' : '') } });
  } else if (c.siteEmail) {
    out.push({ json: { companyName: c.companyName, website: c.website, email: c.siteEmail, contactName: '', offerName: c.offerName,
      evidence: c.evidence, emailNote: 'email via website (' + c.siteEmailType + ')' } });
  }
});
return out;

return $input.all().filter(i => i.json.siteEmail).map(i => ({ json: {
  companyName: i.json.companyName, website: i.json.website, email: i.json.siteEmail, contactName: '', offerName: i.json.offerName,
  evidence: i.json.evidence, emailNote: 'email via website (' + i.json.siteEmailType + ')' } }));

const rows = $input.all().map(i => i.json);
const m = {};
for (const r of rows) { if (r['Key']) m[String(r['Key']).trim()] = r['Value']; }
const bool = (v, d) => (v === undefined || v === '') ? d : ['true','yes','1'].includes(String(v).trim().toLowerCase());
const num = (v, d) => { const n = parseInt(v); return isNaN(n) ? d : n; };
return [{ json: {
  dailyLimit: num(m.dailyLimit, 2), findLimit: num(m.findLimit, 5),
  testMode: bool(m.testMode, true), testEmail: String(m.testEmail || '').trim(),
  autoApprove: bool(m.autoApprove, false),
  senderName: m.senderName || 'Your Name', signatureExtra: m.signatureExtra || '',
  optOutLine: m.optOutLine || "If this isn't relevant, just reply 'no' and I won't email again.",
  hunterMode: String(m.hunterMode || 'fallback').trim().toLowerCase(),
  followUpDay2: num(m.followUpDay2, 3), followUpDay3: num(m.followUpDay3, 4), gapMinutes: num(m.gapMinutes, 2)
}}];

const offers = $input.all().map(i => i.json)
  .filter(o => o['Offer Name'])
  .map(o => ({ name: o['Offer Name'], skill: o['Skill'] || '', pain: o['Pain Signals'] || '', pitch: o['Pitch Angle'] || '', target: o['Target Companies'] || '', region: o['Region'] || '', demo: o['Demo Link'] || '' }));
return [{ json: { offers } }];

const S = $('Parse Settings (Send)').first().json;
const offers = $('Pack Offers').first().json.offers || [];
const leads = $('Read Leads (Send)').all().map(i => i.json);
const inbox = $input.all().map(i => i.json);
const today = new Date(); today.setHours(0, 0, 0, 0);
const daysSince = s => { const d = new Date(s); return isNaN(d) ? 999 : Math.floor((today - d) / 86400000); };
const fromOf = j => JSON.stringify(j.From ?? j.from ?? '').toLowerCase();
const out = [];
const due = [];
for (const l of leads) {
  const email = String(l['Email'] || '').trim().toLowerCase();
  const status = String(l['Status'] || '').trim();
  if (!email) continue;
  if (status === 'Active') {
    const replied = inbox.some(j => fromOf(j).includes(email) && !/mailer-daemon|postmaster/.test(fromOf(j)));
    const bounced = inbox.some(j => /mailer-daemon|postmaster/.test(fromOf(j)) && JSON.stringify(j).toLowerCase().includes(email));
    if (replied) { out.push({ json: { _action: 'mark', email: l['Email'], newStatus: 'Replied', note: 'Reply detected ' + today.toISOString().slice(0, 10) } }); continue; }
    if (bounced) { out.push({ json: { _action: 'mark', email: l['Email'], newStatus: 'Bounced', note: 'Bounce detected ' + today.toISOString().slice(0, 10) } }); continue; }
  }
  const step = parseInt(l['Step'] || 0) || 0;
  let next = 0;
  if (status === 'Approved' && step === 0) next = 1;
  else if (status === 'Active' && step === 1 && daysSince(l['Last Sent Date']) >= S.followUpDay2) next = 2;
  else if (status === 'Active' && step === 2 && daysSince(l['Last Sent Date']) >= S.followUpDay3) next = 3;
  if (!next) continue;
  const o = offers.find(x => x.name === l['Offer']) || {};
  due.push({ nextStep: next, json: { _action: 'send', email: l['Email'], company: l['Company Name'], website: l['Website'], contact: l['Contact Name'] || '',
    offerName: l['Offer'] || '', evidence: l['Signal Evidence'] || '', lastSubject: l['Last Subject'] || '',
    skill: o.skill || '', pain: o.pain || '', pitch: o.pitch || '', demo: o.demo || '', nextStep: next } });
}
due.sort((a, b) => b.nextStep - a.nextStep);   // follow-ups first
return [...out, ...due.slice(0, S.dailyLimit).map(d => ({ json: d.json }))];

const S = $('Parse Settings (Send)').first().json;
const j = $json;
const first = String(j.contact || '').trim();
const rules = j.nextStep === 1 ? 'Email 1 of 3: 70 to 90 words. Tone: professional, courteous and confident, like an experienced consultant writing to a peer; no slang, no exclamation marks, no words in capital letters, never sound desperate or salesy. Do NOT open with praise or flattery (never write "I was impressed", "I admire", "I noticed your great"), and do not open with an introduction of ourselves. Format: three short paragraphs separated by a blank line (use \\n\\n inside the JSON string). Paragraph 1: one specific observation that uses a concrete detail from the snippet (such as number of states, type of operation, services or products) and ties it to a manual or document-heavy process they likely handle, hedged with "often" or "typically"; if the snippet has no concrete detail, ask a short question about how they currently handle that process instead of making a generic industry statement. Paragraph 2: one sentence introducing ourselves, "I work with a small team that builds ..." matched to the offer, with no invented clients or results. Paragraph 3: a soft invitation: if they have a project in view, we would be glad to discuss the requirements, and once the scope is clear we can prepare a short demo of the approach before they commit; then one polite closing question such as "Is this something you are currently exploring?". Do NOT offer a free demo unconditionally. Do not mention price.'
  : j.nextStep === 2 ? 'Email 2 of 3 (follow-up): under 50 words. Add one new useful angle. No guilt, no "just checking in".'
  : 'Email 3 of 3 (last note): under 40 words. Polite, leave the door open.';
const prompt = `You are writing a cold B2B email on behalf of ${S.senderName}, a freelance ML / AI engineer.
${rules}
Recipient: ${first || 'first name unknown'} at ${j.company} (${j.website}).
What we know about the company (web search snippet, may be incomplete): ${j.evidence || 'nothing'}
Offer to pitch: ${j.offerName} - ${j.skill}
Typical manual pain for this offer: ${j.pain}
Pitch angle: ${j.pitch}
Demo/proof link (include it ONCE only if non-empty, and describe it as "a sample of our team's work", never "my work"): ${j.demo || 'none'}
Rules: plain text, no markdown, no emojis, no hype, no links unless a demo link is given. NEVER invent clients, results, numbers or claims. Mention a specific problem only if the snippet supports it; otherwise ask how they currently handle that work. Use hedged wording for time savings ("can", "typically"). Do NOT write a signature or opt-out line (added automatically). Start with "${first ? 'Hi ' + first + ',' : 'Hi there,'}".
Return ONLY JSON: {"subject":"...","body":"..."}. Subject: 3 to 6 words, written as a short question about a specific process at their company (for example "Dispatch paperwork at National Delivery?"), must include the company name, sentence case, and avoid hype or spam words (free, boost, improve, solution, automation, offer, discount).`;
return { json: { ...j, prompt } };

const S = $('Parse Settings (Send)').first().json;
const src = $('Build Email Prompt').item.json;
let subject = 'Quick question for ' + src.company, body = '';
try {
  const p = JSON.parse($json.choices[0].message.content.match(/\{[\s\S]*\}/)[0]);
  subject = p.subject || subject; body = p.body || '';
} catch (e) {}
if (!body) throw new Error('AI returned no usable email for ' + src.company);
body = body.replace(/\\n/g, '\n');
if (src.nextStep > 1 && src.lastSubject) subject = /^re:/i.test(src.lastSubject) ? src.lastSubject : 'Re: ' + src.lastSubject;
const sig = 'Best,\n' + S.senderName + (S.signatureExtra ? '\n' + S.signatureExtra : '');
const full = body.trim() + '\n\n' + sig + '\n\n' + S.optOutLine;
if (S.testMode && !S.testEmail) throw new Error('testMode is TRUE but testEmail is empty in the Settings tab');
return { json: {
  email: src.email, company: src.company, step: src.nextStep, baseSubject: subject, testMode: S.testMode,
  sendTo: S.testMode ? S.testEmail : src.email,
  subject: S.testMode ? '[TEST for ' + src.email + '] ' + subject : subject,
  body: full } };
